mapper.select:
/* selectReqList - Lee MS */ A.CMIT_SE_CD AS CMIT_SE_CD, /* 위원회구분 */ A.ESNTL_LINK_INST_SE_CD AS ESNTL_LINK_INST_SE_CD, /* 필수연계기관구분코드 */ B.OGDP_INST_DTL_SE_CD AS OGDP_INST_DTL_SE_CD, /* 소속기관상세구분코드 */ DECODE(A.ESNTL_LINK_INST_SE_CD, '9', A.INST_NM, B.INST_NM) AS INST_NM, /* 기관명 */ C##RG.DEC_B64(A.ENTRST_PIC_NM_ENCPT) AS ENTRST_PIC_NM, /* 위촉위원성명 */ A.CMIT_JBTTL_SE_CD AS CMIT_JBTTL_SE_CD, /* 위원회직책 */ A.ENTRST_BGNG_YMD AS ENTRST_BGNG_YMD, /* 위촉시작일자 */ A.ENTRST_END_YMD AS ENTRST_END_YMD, /* 위촉종료일자 */ A.NOW_ACTVT_YN AS NOW_ACTVT_YN, /* 현재활동여부 */ TO_CHAR(A.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT, /* 등록일*/ C.INST_NM AS OGDP_INST_NM, A.CMIT_CNSTTN_MNG_NO AS CMIT_CNSTTN_MNG_NO FROM ACA610 A, ACA600 B, SAA000 C /* 필수연계기관관리(B), 통합기관(C) */ WHERE A.ESNTL_LINK_MNG_NO = B.ESNTL_LINK_MNG_NO(+) AND A.INST_NO = C.INST_NO AND A.CMIT_SE_CD LIKE #{CMIT_SE_CD}||'%' AND A.ESNTL_LINK_INST_SE_CD IN ('1', '2', '9') AND A.NOW_ACTVT_YN LIKE #{ACTVT_YN}||'%' AND A.FRST_REG_DT >= TO_DATE(#{BGNG_YMD}||'000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{END_YMD}||'235959', 'YYYYMMDDHH24MISS')
/* 상담복지센터는 모두 조회 */ /* 20230410_권한 쿼리_권한쿼리시작*/
/* 20230220_권한 쿼리_권한쿼리종료*/

/* selectReqList - Lee MS */ A.CMIT_SE_CD AS CMIT_SE_CD, /* 위원회구분 */ A.ESNTL_LINK_INST_SE_CD AS ESNTL_LINK_INST_SE_CD, /* 필수연계기관구분코드 */ B.OGDP_INST_DTL_SE_CD AS OGDP_INST_DTL_SE_CD, /* 소속기관상세구분코드 */ DECODE(A.ESNTL_LINK_INST_SE_CD, '9', A.INST_NM, B.INST_NM) AS INST_NM, /* 기관명 */ C##RG.DEC_B64(A.ENTRST_PIC_NM_ENCPT) AS ENTRST_PIC_NM, /* 위촉위원성명 */ A.CMIT_JBTTL_SE_CD AS CMIT_JBTTL_SE_CD, /* 위원회직책 */ A.ENTRST_BGNG_YMD AS ENTRST_BGNG_YMD, /* 위촉시작일자 */ A.ENTRST_END_YMD AS ENTRST_END_YMD, /* 위촉종료일자 */ A.NOW_ACTVT_YN AS NOW_ACTVT_YN, /* 현재활동여부 */ TO_CHAR(A.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT, /* 등록일*/ C.INST_NM AS OGDP_INST_NM, A.CMIT_CNSTTN_MNG_NO AS CMIT_CNSTTN_MNG_NO FROM ACA610 A, ACA600 B, SAA000 C /* 필수연계기관관리(B), 통합기관(C) */ WHERE A.ESNTL_LINK_MNG_NO = B.ESNTL_LINK_MNG_NO(+) AND A.INST_NO = C.INST_NO AND A.NOW_ACTVT_YN LIKE #{ACTVT_YN}||'%' AND A.FRST_REG_DT >= TO_DATE(#{BGNG_YMD}||'000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{END_YMD}||'235959', 'YYYYMMDDHH24MISS')
AND C##RG.DEC_B64(A.ENTRST_PIC_NM_ENCPT) LIKE '%'||#{ENTRST_PIC_NM}||'%'
AND A.ESNTL_LINK_INST_SE_CD LIKE #{INST_SE}||'%'
AND A.ESNTL_LINK_INST_SE_CD IN ('3', '4')
/* 20230410_권한 쿼리_권한쿼리시작*/
/* 20230220_권한 쿼리_권한쿼리종료*/

